head.script:
let objParent = $p.parent();
let eCount_1 = 0;
let eCount_2 = 0;



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[common > E > onmousemove]<br/>컴포넌트 영역에서 마우스 포인터가 이동할 때 발생합니다.",
    "validation" : [
        "컴포넌트 영역에서 마우스 포인터가 이동할 때 발생하여야 합니다.",
        "컴포넌트가 disabled 속성을 지원하는 경우 Disabled 상태이면 이벤트가 발생하지 않습니다.",
    ]
} 



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // comp 생성 호출
    objParent.scwin.comp_init(); 
}



objParent.scwin.target1_onmousemove = function (e) {
    // 이벤트 3번만 발생하게 처리
    if(eCount_1 < 3) {
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onmousemove 이벤트 발생=====");
        wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);   

        if(eCount_1 == 2)
            wf_body_bottom.getObj("scwin").setReturnValue("...");
    }

    eCount_1 += 1;
}


objParent.scwin.target2_onmousemove = function (e) {
    // 이벤트 3번만 발생하게 처리
    if(eCount_2 < 3) {
        wf_body_bottom.getObj("scwin").setReturnValue("=====target2_onmousemove 이벤트 발생=====");
        wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);   

        if(eCount_2 == 2)
            wf_body_bottom.getObj("scwin").setReturnValue("...");
    }

    eCount_2 += 1;
}
